import { useCallback, useEffect, useMemo, useState } from 'react';
import { useIntl } from 'react-intl';
import { useDispatch, useSelector } from 'react-redux';

import { ExploreFurther } from 'components';
import { featureToggles } from 'config/featureToggle';
import { useLastDataRefresh } from 'contexts';
import { usesPerformanceToolTimePeriod } from 'domain/Filter';
import {
  useBffData,
  useFeatureToggle,
  useMediaQuery,
  usePageFilterApplied,
  usePageFilterData,
  useSubFilters,
} from 'hooks';
import { AISummary } from 'pages/components/AISummary';
import { DrillDownErrorState } from 'pages/components/ValueCreation';
import { StyledValueCreationPageContainer } from 'pages/pillars/ValueCreation/styles';
import { evaluateDrillDownFullPageErrorState } from 'pages/pillars/ValueCreation/utils/evaluateDrillDownFullPageErrorState';
import { setPerformanceToolVolumeChartPeriodType } from 'redux/slices/filters';
import { selectPage } from 'redux/slices/filters/selectors';
import { RootState } from 'redux/types';
import { resolveTimePeriodSelection } from 'utils/timePeriod/timePeriodAvailability';

import {
  PERFORMANCE_TOOL_BIG_NUMBERS_COMPONENT_ID,
  PERFORMANCE_TOOL_LINE_BAR_CHARTS_COMPONENT_ID,
  PERFORMANCE_TOOL_NET_REVENUE_BIG_NUMBERS_BFF_ID,
  PERFORMANCE_TOOL_NET_REVENUE_LINE_BAR_CHARTS_BFF_ID,
  PERFORMANCE_TOOL_PAGE_NAME,
  PERFORMANCE_TOOL_VOLUME_BIG_NUMBERS_BFF_ID,
  PERFORMANCE_TOOL_VOLUME_CONTRIBUTION_WATERFALL_BFF_ID,
  PERFORMANCE_TOOL_VOLUME_LINE_BAR_CHARTS_BFF_ID,
} from '../../../constants';
import {
  ComponentId,
  useKpiDrillDownFullPageEmptyState,
  usePerformanceToolData,
  usePerformanceToolDrillDownAiSummary,
} from '../../../hooks';
import {
  deriveTimePeriodHighlightedIndexes,
  getCanonicalPerformanceToolTimePeriodType,
  getPerformanceToolRequestPeriodType,
  getPerformanceToolSubFilters,
  getVolumeBigNumbersApiPeriodType,
  getVolumeBigNumbersCardPeriodType,
  getVolumeBigNumbersSelectedCardIndex,
  isContributionEmpty,
  isOvertimePerformanceEmpty,
  isOvertimeTrendsEmpty,
  usesKpiDrillDownFullPageEmptyState,
  usesPerformanceToolBigNumbersCardNavigation,
} from '../../../utils';
import { KpiDrillDownEmptyTimePeriodState } from '../../KpiDrillDownEmptyState';
import { PerformanceSection } from '../../Sections';
import { KpiDrillDownProps } from './types';

const BFF_ID_PREFIX = 'value-creation_performance-tool_drill-down';

type KpiIds = {
  bigNumbersComponentId: Extract<
    ComponentId,
    'big-numbers' | 'overtime-performance'
  >;
  bigNumbersViewId: string;
  lineBarChartsComponentId: Extract<
    ComponentId,
    'line-bar-charts' | 'overtime-trends'
  >;
  lineBarChartsViewId: string;
  waterfallViewId: string;
};

const KPI_IDS: Record<string, KpiIds | undefined> = {
  volume: {
    bigNumbersComponentId: PERFORMANCE_TOOL_BIG_NUMBERS_COMPONENT_ID,
    bigNumbersViewId: PERFORMANCE_TOOL_VOLUME_BIG_NUMBERS_BFF_ID,
    lineBarChartsComponentId: PERFORMANCE_TOOL_LINE_BAR_CHARTS_COMPONENT_ID,
    lineBarChartsViewId: PERFORMANCE_TOOL_VOLUME_LINE_BAR_CHARTS_BFF_ID,
    waterfallViewId: PERFORMANCE_TOOL_VOLUME_CONTRIBUTION_WATERFALL_BFF_ID,
  },
  'net-revenue': {
    bigNumbersComponentId: PERFORMANCE_TOOL_BIG_NUMBERS_COMPONENT_ID,
    bigNumbersViewId: PERFORMANCE_TOOL_NET_REVENUE_BIG_NUMBERS_BFF_ID,
    lineBarChartsComponentId: PERFORMANCE_TOOL_LINE_BAR_CHARTS_COMPONENT_ID,
    lineBarChartsViewId: PERFORMANCE_TOOL_NET_REVENUE_LINE_BAR_CHARTS_BFF_ID,
    waterfallViewId: `${BFF_ID_PREFIX}_net-revenue_contribution`,
  },
};
const SKELETON_PROPS = {
  height: '168px',
  width: '100%',
  length: 3,
  borderRadius: 'medium' as const,
};

export const KpiDrillDown: React.FC<KpiDrillDownProps> = ({
  config,
  onFilterChange,
}) => {
  const {
    kpiSlug,
    kpiGroup,
    waterfallConfig,
    measure,
    periodValues,
    bigNumbersTitle = 'Overtime Performance',
    bigNumbersTooltip,
    showLineDataLabels = true,
    lineChartHighlightStrategy = 'bff',
  } = config;
  const { formatMessage } = useIntl();
  const dispatch = useDispatch();
  const { lastDataRefreshKpisDateMonthYear } = useLastDataRefresh();
  const kpiGroupDtEnd = lastDataRefreshKpisDateMonthYear?.[kpiGroup];

  const isLargeScreen = useMediaQuery('(min-width: 1440px)');
  const { applied } = usePageFilterApplied(PERFORMANCE_TOOL_PAGE_NAME);
  const { appliedDataFilters } = usePageFilterData(PERFORMANCE_TOOL_PAGE_NAME);
  const { activeSubFilters } = useSubFilters();
  const timePeriodApplyToken = useSelector(
    (state: RootState) =>
      selectPage(PERFORMANCE_TOOL_PAGE_NAME)(state)
        ?.performanceToolVolumeTimePeriodApplyToken ?? 0,
  );

  const subFilters = useMemo(
    () => getPerformanceToolSubFilters(applied),
    [applied],
  );
  const usesTimePeriod = usesPerformanceToolTimePeriod(appliedDataFilters);
  const timePeriodSelection = usesTimePeriod
    ? resolveTimePeriodSelection(
        applied.period_type,
        applied.dt_end,
        kpiGroupDtEnd,
      )
    : null;
  const requestPeriodType =
    getPerformanceToolRequestPeriodType(timePeriodSelection);
  const hasInvalidTimePeriod = usesTimePeriod && !requestPeriodType;
  const [selectedCardPeriodType, setSelectedCardPeriodType] = useState<
    string | null
  >(null);

  useEffect(() => {
    setSelectedCardPeriodType(null);
  }, [
    applied.dt_end,
    applied.period_type,
    requestPeriodType,
    timePeriodApplyToken,
  ]);

  const usesBigNumbersCardNavigation =
    usesPerformanceToolBigNumbersCardNavigation(kpiSlug, usesTimePeriod);

  const apiPeriodType = useMemo(() => {
    if (!requestPeriodType) return null;

    if (usesBigNumbersCardNavigation && selectedCardPeriodType) {
      return (
        getVolumeBigNumbersApiPeriodType(
          selectedCardPeriodType,
          applied.period_type,
        ) ?? requestPeriodType
      );
    }

    return requestPeriodType;
  }, [
    applied.period_type,
    requestPeriodType,
    selectedCardPeriodType,
    usesBigNumbersCardNavigation,
  ]);

  const activeCardPeriodType = useMemo(() => {
    if (!usesBigNumbersCardNavigation || !requestPeriodType) return null;

    return (
      selectedCardPeriodType ??
      getVolumeBigNumbersCardPeriodType(requestPeriodType, applied.dt_end)
    );
  }, [
    applied.dt_end,
    requestPeriodType,
    selectedCardPeriodType,
    usesBigNumbersCardNavigation,
  ]);

  useEffect(() => {
    if (!usesBigNumbersCardNavigation) {
      dispatch(setPerformanceToolVolumeChartPeriodType({ periodType: null }));
      return;
    }

    dispatch(
      setPerformanceToolVolumeChartPeriodType({
        periodType: activeCardPeriodType,
      }),
    );

    return () => {
      dispatch(setPerformanceToolVolumeChartPeriodType({ periodType: null }));
    };
  }, [activeCardPeriodType, dispatch, usesBigNumbersCardNavigation]);

  const legacyPeriodFilters = usesTimePeriod
    ? {}
    : {
        timeframe: applied.periods,
        period_type: applied.periods,
      };

  const kpiIds = KPI_IDS[kpiSlug];

  const lineBarChartsViewId =
    kpiIds?.lineBarChartsViewId ??
    `${BFF_ID_PREFIX}_${kpiSlug}_overtime-trends`;

  const lineBarChartsComponentId: Extract<
    ComponentId,
    'line-bar-charts' | 'overtime-trends'
  > = kpiIds?.lineBarChartsComponentId ?? 'overtime-trends';

  const waterfallViewId =
    kpiIds?.waterfallViewId ?? `${BFF_ID_PREFIX}_${kpiSlug}_contribution`;

  const bigNumbersViewId =
    kpiIds?.bigNumbersViewId ??
    `${BFF_ID_PREFIX}_${kpiSlug}_overtime-performance`;

  const bigNumbersComponentId: Extract<
    ComponentId,
    'big-numbers' | 'overtime-performance'
  > = kpiIds?.bigNumbersComponentId ?? 'overtime-performance';

  const bigNumbersBffData = useBffData({
    id: bigNumbersViewId,
    kpiGroup,
    subFilters: {
      ...subFilters,
      ...(usesTimePeriod ? {} : { timeframe: 'YTD' }),
      ...(requestPeriodType && timePeriodSelection
        ? {
            period_type: requestPeriodType,
            dt_end: timePeriodSelection.dtEnd,
          }
        : {}),
      waterfall_filter: activeSubFilters?.waterfall_view_by,
      kpi: applied.kpis,
    },
    skipMainFilters: false,
    skipRequest: hasInvalidTimePeriod,
  });

  const overtimeBffData = useBffData({
    id: lineBarChartsViewId,
    kpiGroup,
    subFilters: {
      ...subFilters,
      ...legacyPeriodFilters,
      ...(apiPeriodType && timePeriodSelection
        ? {
            period_type: apiPeriodType,
            dt_end: timePeriodSelection.dtEnd,
          }
        : {}),
      waterfall_filter: activeSubFilters?.waterfall_view_by,
      kpi: applied.kpis,
    },
    skipMainFilters: false,
    skipRequest: hasInvalidTimePeriod,
  });

  const waterfallBffData = useBffData({
    id: waterfallViewId,
    kpiGroup,
    subFilters: {
      ...subFilters,
      ...legacyPeriodFilters,
      ...(apiPeriodType && timePeriodSelection
        ? {
            period_type: apiPeriodType,
            dt_end: timePeriodSelection.dtEnd,
          }
        : {}),
      waterfall_filter: activeSubFilters?.waterfall_view_by,
      kpi: applied.kpis,
    },
    skipMainFilters: false,
    skipRequest: hasInvalidTimePeriod,
  });

  const bigNumbersData = usePerformanceToolData(
    [bigNumbersComponentId],
    bigNumbersBffData,
  );

  const overtimeData = usePerformanceToolData(
    [lineBarChartsComponentId],
    overtimeBffData,
  );

  const rawLineBarChartsData =
    overtimeData[lineBarChartsComponentId] ?? undefined;

  const lineBarChartsData = useMemo(() => {
    if (
      lineChartHighlightStrategy !== 'time-period' ||
      !rawLineBarChartsData?.lineChart
    ) {
      return rawLineBarChartsData;
    }

    const { labels, datasets } = rawLineBarChartsData.lineChart;
    const highlightedIndexes = deriveTimePeriodHighlightedIndexes({
      periodType:
        getCanonicalPerformanceToolTimePeriodType(apiPeriodType) ??
        applied.period_type,
      dtEnd: applied.dt_end,
      cutoffDate: kpiGroupDtEnd,
      labels,
      datasets,
    });

    return {
      ...rawLineBarChartsData,
      lineChart: {
        ...rawLineBarChartsData.lineChart,
        highlightedIndexes,
      },
    };
  }, [
    applied.dt_end,
    applied.period_type,
    apiPeriodType,
    kpiGroupDtEnd,
    lineChartHighlightStrategy,
    rawLineBarChartsData,
  ]);

  const waterfallData = usePerformanceToolData(
    ['contribution'],
    waterfallBffData,
  );

  const waterfallVariant = useMemo(
    () => (isLargeScreen ? 'large' : 'small'),
    [isLargeScreen],
  );

  const contributionData = waterfallData['contribution'] ?? undefined;

  const shouldShowKpiDrillDownEmptyState =
    usesKpiDrillDownFullPageEmptyState(kpiSlug);

  const fullPageStateViews = useMemo(
    () => [
      {
        loading: bigNumbersBffData.loading,
        error: bigNumbersBffData.error,
        isEmpty: isOvertimePerformanceEmpty(
          bigNumbersData[bigNumbersComponentId],
        ),
        skipped: hasInvalidTimePeriod,
      },
      {
        loading: overtimeBffData.loading,
        error: overtimeBffData.error,
        isEmpty: isOvertimeTrendsEmpty(lineBarChartsData),
        skipped: hasInvalidTimePeriod,
      },
      {
        loading: waterfallBffData.loading,
        error: waterfallBffData.error,
        isEmpty: isContributionEmpty(contributionData, waterfallVariant),
        skipped: hasInvalidTimePeriod,
      },
    ],
    [
      bigNumbersBffData.loading,
      bigNumbersBffData.error,
      bigNumbersComponentId,
      bigNumbersData,
      contributionData,
      hasInvalidTimePeriod,
      lineBarChartsData,
      overtimeBffData.loading,
      overtimeBffData.error,
      waterfallBffData.loading,
      waterfallBffData.error,
      waterfallVariant,
    ],
  );

  const showFullPageError =
    shouldShowKpiDrillDownEmptyState &&
    evaluateDrillDownFullPageErrorState(fullPageStateViews);

  const showFullPageEmpty = useKpiDrillDownFullPageEmptyState({
    enabled: shouldShowKpiDrillDownEmptyState,
    views: fullPageStateViews,
  });

  const selectedBigNumberIndex = useMemo(() => {
    if (usesBigNumbersCardNavigation) {
      return getVolumeBigNumbersSelectedCardIndex(
        bigNumbersData[bigNumbersComponentId] ?? undefined,
        activeCardPeriodType,
      );
    }

    const index = periodValues.indexOf(applied.periods as string);
    return Math.max(index, 0);
  }, [
    activeCardPeriodType,
    applied.periods,
    bigNumbersComponentId,
    bigNumbersData,
    periodValues,
    usesBigNumbersCardNavigation,
  ]);

  const handleBigNumbersSelect = useCallback(
    (index: number) => {
      const cards = bigNumbersData[bigNumbersComponentId];

      if (!cards?.[index]) {
        return;
      }

      if (usesBigNumbersCardNavigation) {
        const periodType = cards[index].period_type;

        if (periodType) {
          setSelectedCardPeriodType(periodType);
        }

        return;
      }

      onFilterChange('periods', periodValues[index]);
    },
    [
      bigNumbersComponentId,
      bigNumbersData,
      onFilterChange,
      periodValues,
      usesBigNumbersCardNavigation,
    ],
  );

  const showDrivers = useMemo(() => {
    return !!applied.sub_brands && applied.sub_brands !== 'All';
  }, [applied]);

  const { aiSummaryEntry, aiSummaryFilters, isAiSummaryEnabled } =
    usePerformanceToolDrillDownAiSummary(kpiSlug, applied);

  const [commercialResultsEnabled, commercialResultsLoading] = useFeatureToggle(
    featureToggles.pillar.valueCreation.submenus.commercialResults.id,
  );

  const showExploreFurther = useMemo(
    () =>
      kpiSlug === 'volume' &&
      commercialResultsEnabled &&
      !commercialResultsLoading,
    [kpiSlug, commercialResultsEnabled, commercialResultsLoading],
  );
  const exploreFurtherCards = useMemo(() => {
    return ['commercialResults', 'driversDecomposition'].map((card) => {
      return {
        title: formatMessage({
          id: `ValueCreation.PerformanceTool.exploreFurther.${card}.title`,
        }),
        description: formatMessage({
          id: `ValueCreation.PerformanceTool.exploreFurther.${card}.description`,
        }),
        linkLabel: formatMessage({
          id: `ValueCreation.PerformanceTool.exploreFurther.${card}.linkLabel`,
        }),
        linkHref: formatMessage({
          id: `ValueCreation.PerformanceTool.exploreFurther.${card}.linkHref`,
        }),
        abbreviation: formatMessage({
          id: `ValueCreation.PerformanceTool.exploreFurther.${card}.abbreviation`,
        }),
        enabled:
          card === 'commercialResults' ? !!commercialResultsEnabled : false,
      };
    });
  }, [commercialResultsEnabled, formatMessage]);

  if (showFullPageError) {
    return (
      <StyledValueCreationPageContainer $centered>
        <DrillDownErrorState dataTestId="performance-tool-error-state" />
      </StyledValueCreationPageContainer>
    );
  }

  if (showFullPageEmpty) {
    return (
      <StyledValueCreationPageContainer $centered>
        <KpiDrillDownEmptyTimePeriodState />
      </StyledValueCreationPageContainer>
    );
  }

  return (
    <StyledValueCreationPageContainer>
      {isAiSummaryEnabled && aiSummaryEntry && (
        <AISummary
          pageName={PERFORMANCE_TOOL_PAGE_NAME}
          kpiGroup={kpiGroup}
          summaryPageIdentifier={aiSummaryEntry.summaryPageIdentifier}
          subFilters={aiSummaryFilters}
          dataTestId={`performance-tool-drilldown-ai-summary-${kpiSlug}`}
        />
      )}

      <PerformanceSection
        measure={measure}
        volumeChartPeriodType={activeCardPeriodType}
        bigNumbersProps={{
          title: bigNumbersTitle,
          tooltip: bigNumbersTooltip,
          data: bigNumbersData[bigNumbersComponentId] ?? undefined,
          loading: bigNumbersBffData.loading,
          error: bigNumbersBffData.error,
          skeletonProps: SKELETON_PROPS,
          onSelect: handleBigNumbersSelect,
          defaultSelected: selectedBigNumberIndex,
        }}
        lineBarChartsData={lineBarChartsData}
        waterfallData={contributionData}
        waterfallRequest={waterfallBffData}
        lineBarChartsRequest={overtimeBffData}
        waterfallVariant={waterfallVariant}
        showDrivers={showDrivers}
        waterfallConfig={waterfallConfig}
        showLineDataLabels={showLineDataLabels}
      />

      {showExploreFurther && (
        <ExploreFurther
          filterPageName={PERFORMANCE_TOOL_PAGE_NAME}
          cards={exploreFurtherCards}
          dataTestId={PERFORMANCE_TOOL_PAGE_NAME}
        />
      )}
    </StyledValueCreationPageContainer>
  );
};
